module square_difference (\n    input wire [31:0] n,\n    output reg [31:0] m,\n    output reg [31:0] k,\n    output reg valid\n);\n    always @(*) begin\n        if (n[0]) begin\n            // Odd case\n            m = (n + 32'd1) >> 1;\n            k = (n - 32'd1) >> 1;\n            valid = 1'b1;\n        end else if (n[1:0] == 2'b00) begin\n            // Divisible by 4\n            m = (n >> 2) + 32'd1;\n            k = (n >> 2) - 32'd1;\n            valid = 1'b1;\n        end else begin\n            // Invalid case\n            m = 32'd0;\n            k = 32'd0;\n            valid = 1'b0;\n        end\n    end\nendmodule